import {statuses,statusCode} from './core.mjs';
export function pause(ms,signal){return new Promise((resolve,reject)=>{signal?.throwIfAborted();const cancel=()=>{clearTimeout(timer);reject(new DOMException('Cancelled','AbortError'));};const timer=setTimeout(()=>{signal?.removeEventListener('abort',cancel);resolve();},ms);signal?.addEventListener('abort',cancel,{once:true});});}
export function createTransport({fetchImpl=globalThis.fetch,interval=2100,sleep=pause}={}){let next=0,chain=Promise.resolve();return function request(url,options={},signal){const work=async()=>{for(let attempt=0;attempt<4;attempt++){signal?.throwIfAborted();await sleep(Math.max(0,next-Date.now()),signal);let r;try{r=await fetchImpl(url,{...options,signal});}catch(e){if(signal?.aborted)throw e;if(attempt===3)throw Error('The official service could not be reached. Check your connection or local connector.');next=Date.now()+2**(attempt+1)*1000;continue;}next=Date.now()+interval;const remaining=r.headers.get('x-ratelimit-remaining'),reset=Number(r.headers.get('x-ratelimit-reset'));if(remaining==='0')next=Math.max(next,reset?reset*1000+1000:Date.now()+60000);if((r.status===429||r.status>=500)&&attempt<3){const retry=r.headers.get('retry-after');const wait=retry?(Number.isFinite(Number(retry))?Number(retry)*1000:Math.max(0,Date.parse(retry)-Date.now())):2**(attempt+1)*1000;next=Math.max(next,Date.now()+wait);continue;}if(r.status===401)throw Error('Your authorization expired or was rejected. Sign in again.');if(!r.ok)throw Error(`The official service returned HTTP ${r.status}. No response body or credentials were logged.`);let json;try{json=await r.json();}catch{throw Error('The service returned an unreadable response.');}if(json.errors?.length)throw Error('The service rejected the request. Check your account, media ID and fields.');return json;}};const task=chain.then(work,work);chain=task.catch(()=>{});return task;};}
function readStatus(value,rereading=false){if(rereading)return 'Rereading';return ({CURRENT:'Reading',reading:'Reading',COMPLETED:'Completed',completed:'Completed',PAUSED:'OnHold',on_hold:'OnHold',DROPPED:'Dropped',dropped:'Dropped',PLANNING:'PlanToRead',plan_to_read:'PlanToRead',REPEATING:'Rereading'})[value]??'Unknown';}
function fullDate(d){return d?.year&&d?.month&&d?.day?`${d.year.toString().padStart(4,'0')}-${d.month.toString().padStart(2,'0')}-${d.day.toString().padStart(2,'0')}`:'';}
function fuzzyDate(s){const [year,month,day]=s.split('-').map(Number);return {year,month,day};}
export function createApi({destination='AniList',token='',clientId='',transport=createTransport()}={}){let userId;const headers=()=>({'content-type':'application/json',...(token&&destination==='AniList'?{authorization:`Bearer ${token}`}:{})});const query=async(q,variables,signal)=>(await transport('https://graphql.anilist.co',{method:'POST',headers:headers(),body:JSON.stringify({query:q,variables})},signal)).data;const mal=async(path,signal)=>transport('https://api.myanimelist.net/v2/'+path,{headers:token?{authorization:`Bearer ${token}`}:{'X-MAL-CLIENT-ID':clientId}},signal);return {
 async account(signal){if(!token)throw Error('Sign in first.');if(destination==='MyAnimeList')return (await mal('users/@me',signal)).name;const r=await query('query{Viewer{id name mediaListOptions{scoreFormat}}}',{},signal);userId=r.Viewer.id;return `${r.Viewer.name} · ${r.Viewer.mediaListOptions.scoreFormat}`;},
 async search(title,signal){if(destination==='MyAnimeList'){if(!token&&!clientId){const r=await query('query($q:String){Page(perPage:20){media(search:$q,type:MANGA){'+mediaFields+'}}}',{q:title},signal);return r.Page.media.map(anilistCandidate).filter(c=>c.malId).map(c=>({...c,id:c.malId,chapters:null,volumes:null}));}if(title.length<3)return [];const r=await mal('manga?q='+encodeURIComponent(title)+'&nsfw=true&limit=20&fields=alternative_titles,authors,start_date,media_type,num_chapters,num_volumes,nsfw',signal);return r.data.map(({node})=>malCandidate(node));}const r=await query('query($q:String){Page(perPage:20){media(search:$q,type:MANGA){'+mediaFields+'}}}',{q:title},signal);return r.Page.media.map(anilistCandidate);},
 async lookup(ref,signal){if(!Number.isInteger(ref.id)||ref.id<1)return null;const args=ref.service==='MyAnimeList'?'idMal:$id':'id:$id';const r=await query('query($id:Int){Media('+args+',type:MANGA){'+mediaFields+'}}',{id:ref.id},signal);if(!r.Media)return null;const c=anilistCandidate(r.Media);if(destination==='AniList')return c;return c.malId?{...c,id:c.malId,chapters:null,volumes:null}:null;},
 async list(signal){if(destination!=='AniList')return null;if(!userId)await this.account(signal);const found=new Map();for(let chunk=1;chunk<=30;chunk++){const r=await query('query($user:Int,$chunk:Int){MediaListCollection(userId:$user,type:MANGA,perChunk:500,chunk:$chunk){hasNextChunk lists{entries{id mediaId status score(format:POINT_100) progress progressVolumes startedAt{year month day} completedAt{year month day}}}}}',{user:userId,chunk},signal);const collection=r.MediaListCollection;if(!collection||!Array.isArray(collection.lists))throw Error('Could not read the account list safely. Retry the dry run.');for(const list of collection.lists)for(const m of list.entries??[])found.set(m.mediaId,{mediaId:m.mediaId,listId:m.id,status:readStatus(m.status),score:Math.round(m.score??0),chapters:m.progress??0,volumes:m.progressVolumes??0,startDate:fullDate(m.startedAt),finishDate:fullDate(m.completedAt)});if(!collection.hasNextChunk)return {entries:[...found.values()],complete:found.size<11000};}return {entries:[...found.values()],complete:false};},
 async get(id,signal){if(!Number.isInteger(id)||id<1)throw Error('Invalid media ID.');if(destination==='MyAnimeList'){const r=await mal(`manga/${id}?fields=my_list_status`,signal),m=r.my_list_status;return !m?null:{mediaId:id,listId:null,status:readStatus(m.status,m.is_rereading),score:m.score??0,chapters:m.num_chapters_read??0,volumes:m.num_volumes_read??0,startDate:'',finishDate:''};}if(!userId)await this.account(signal);const r=await query('query($id:Int,$user:Int){Media(id:$id,type:MANGA){id} Page(perPage:1){mediaList(mediaId:$id,userId:$user,type:MANGA){id status score(format:POINT_100) progress progressVolumes startedAt{year month day} completedAt{year month day}}}}',{id,user:userId},signal);if(!r.Media)throw Error('This media ID is not a manga.');const m=r.Page.mediaList[0];return m?{mediaId:id,listId:m.id,status:readStatus(m.status),score:Math.round(m.score??0),chapters:m.progress??0,volumes:m.progressVolumes??0,startDate:fullDate(m.startedAt),finishDate:fullDate(m.completedAt)}:null;},
 async save(e,signal){if(!token)throw Error('Sign in first.');if(!Number.isInteger(e.mediaId)||e.mediaId<1||!statuses.includes(e.status)||e.status==='Unknown'||!Number.isInteger(e.score)||e.score<0||e.score>(destination==='AniList'?100:10)||![e.chapters,e.volumes].every(n=>Number.isInteger(n)&&n>=0))throw Error('Invalid import values. Run a new dry run.');if(destination==='MyAnimeList'){const form=new URLSearchParams({status:statusCode(destination,e.status),is_rereading:String(e.status==='Rereading'),score:String(e.score),num_chapters_read:String(e.chapters),num_volumes_read:String(e.volumes)});await transport(`https://api.myanimelist.net/v2/manga/${e.mediaId}/my_list_status`,{method:'PATCH',headers:{authorization:`Bearer ${token}`,'content-type':'application/x-www-form-urlencoded'},body:form.toString()},signal);return;}const variables={list:e.listId,id:e.mediaId,status:statusCode(destination,e.status),score:e.score,chapters:e.chapters,volumes:e.volumes};if(e.startDate)variables.start=fuzzyDate(e.startDate);if(e.finishDate)variables.end=fuzzyDate(e.finishDate);await query('mutation($list:Int,$id:Int,$status:MediaListStatus,$score:Int,$chapters:Int,$volumes:Int,$start:FuzzyDateInput,$end:FuzzyDateInput){SaveMediaListEntry(id:$list,mediaId:$id,status:$status,scoreRaw:$score,progress:$chapters,progressVolumes:$volumes,startedAt:$start,completedAt:$end){id}}',variables,signal);}
};}

const mediaFields='id idMal title{romaji english native} synonyms isAdult format startDate{year} chapters volumes staff(perPage:10){nodes{name{full}}}';
function anilistCandidate(m){return {id:m.id,anilistId:m.id,malId:m.idMal??null,title:m.title.english||m.title.romaji||m.title.native,native:m.title.native??'',contentRating:m.isAdult===true?'NSFW':m.isAdult===false?'SFW':'Unknown',alternatives:[m.title.romaji,...(m.synonyms??[])].filter(Boolean),author:(m.staff?.nodes??[]).map(s=>s.name.full).join(', '),year:m.startDate?.year??null,format:m.format,chapters:m.chapters,volumes:m.volumes};}
function malCandidate(m){return {id:m.id,malId:m.id,anilistId:null,title:m.title,native:m.alternative_titles?.ja??'',contentRating:m.nsfw==='white'?'SFW':['gray','black'].includes(m.nsfw)?'NSFW':'Unknown',alternatives:[m.alternative_titles?.en,...(m.alternative_titles?.synonyms??[])].filter(Boolean),author:(m.authors??[]).map(a=>((a.node.first_name??'')+' '+(a.node.last_name??'')).trim()).join(', '),year:Number(m.start_date?.slice(0,4))||null,format:m.media_type,chapters:m.num_chapters||null,volumes:m.num_volumes||null};}
